import{_ as a,o as e,c as s,a6 as r}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"完整提示词怎么写","description":"","frontmatter":{"id":"prompt-writing","title":"完整提示词怎么写","chapter":"02","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":12,"content_kind":"方法说明"},"headers":[],"relativePath":"start/prompt-writing.md","filePath":"start/prompt-writing.md"}'),d={name:"start/prompt-writing.md"};function i(n,t,p,o,l,h){return e(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="完整提示词怎么写-从模糊要求改到可操作任务" tabindex="-1">完整提示词怎么写，从模糊要求改到可操作任务 <a class="header-anchor" href="#完整提示词怎么写-从模糊要求改到可操作任务" aria-label="Permalink to &quot;完整提示词怎么写，从模糊要求改到可操作任务&quot;">​</a></h1><p>提示词应当让工具知道要改哪个文件、改哪里、最后交什么。先写商品身份和任务，再写构图与光线。多个用途拆开写，白底主图、场景副图、尺寸排版不能同时挤在一条“帮我做高级详情页”里。</p><h2 id="_1-先把一句模糊要求补成六项" tabindex="-1">1. 先把一句模糊要求补成六项 <a class="header-anchor" href="#_1-先把一句模糊要求补成六项" aria-label="Permalink to &quot;1. 先把一句模糊要求补成六项&quot;">​</a></h2><p>“做一张高级的榨汁杯图”缺少素材、用途、构图和限制。按下面六项补全。</p><table tabindex="0"><thead><tr><th>项目</th><th>本次填写</th></tr></thead><tbody><tr><td>输入</td><td>JB01-white正面实拍，是唯一商品外观依据</td></tr><tr><td>任务</td><td>厨房场景副图，不是主图或参数图</td></tr><tr><td>保留</td><td>杯盖、按钮、底座、标识、颜色与比例</td></tr><tr><td>改动</td><td>背景与合理接触阴影</td></tr><tr><td>表达</td><td>左前方自然光，右侧商品，左上留白</td></tr><tr><td>输出</td><td>一张无字方图，下载原文件</td></tr></tbody></table><h2 id="_2-完整词可以这样写" tabindex="-1">2. 完整词可以这样写 <a class="header-anchor" href="#_2-完整词可以这样写" aria-label="Permalink to &quot;2. 完整词可以这样写&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据上传的JB01-white正面实拍，制作一张厨房场景商品副图。真实产品照片是唯一外观依据，保留杯盖、杯体、按钮、底座、标识位置、颜色和比例，只调整背景与合理的接触阴影。</span></span>
<span class="line"><span>场景是明亮厨房浅木台面，柔和自然光从左前方照入。商品在右侧，左上留简洁空间用于后期标题，少量水果在远处，不遮商品，不暗示随商品发货。真实产品摄影，材质不过度修饰。</span></span>
<span class="line"><span>输出一张方形无字底图，不生成文字、数字、徽章、图标、虚构配件、内部结构和水印。若无法保持商品外观，改为只生成空台面背景，并说明需要把原商品层合成回去。</span></span></code></pre></div><h2 id="_3-三类提示词要交给不同环节" tabindex="-1">3. 三类提示词要交给不同环节 <a class="header-anchor" href="#_3-三类提示词要交给不同环节" aria-label="Permalink to &quot;3. 三类提示词要交给不同环节&quot;">​</a></h2><p>规划词给文字助手，输出职责表、拍摄清单和准确文案。生图词给支持参考图的图像工具，输出候选图片。局部修图词给有选区或蒙版的编辑工具，明确修改区域。把参数表交给普通文生图模型，并不会得到可编辑文字层。</p><p>例如尺寸图先让文字助手整理数值、单位与线条位置，再在PS/Photopea排版；需要背景留白时只让图像工具做无字底图。模型支持文字生成时仍可尝试短标题，但商品参数、警示和多语言准确文本要逐字复核。</p><h2 id="_4-一次只改一个可见问题" tabindex="-1">4. 一次只改一个可见问题 <a class="header-anchor" href="#_4-一次只改一个可见问题" aria-label="Permalink to &quot;4. 一次只改一个可见问题&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以这张已经通过商品核对的图为输入，只调整左上背景，把水果移出标题留白区。保持商品像素、尺寸、角度、颜色、光向和接触阴影。不要重新设计全图，不改文字和商品结构。</span></span></code></pre></div><p>若编辑工具没有局部区域控制，不能保证只改一处，回图层文件移动背景或裁切。记录本次问题、改动词和结果，避免每次都重写风格导致整套漂移。完整变体模板可查<a href="./../prompts/P01">P01</a>和<a href="./../prompts/P06">P06</a>，连续操作看<a href="./../ecommerce/image-set">套图教程</a>。</p>`,13)])])}const m=a(d,[["render",i]]);export{_ as __pageData,m as default};
